INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39172,221,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M3','challenge','For an arithmetic progression with first term a and common difference d, which are correct?','aâ‚™=a+(n-1)d','Sâ‚™=n[2a+(n-1)d]/2','If d=0 all terms are equal','Sâ‚™=n(a+d) for all n','A','The standard nth-term and sum formulas hold, and d=0 gives a constant sequence.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39173,222,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M4','challenge','Let f be differentiable at x=a. Which statements must be true?','f is continuous at a','The left and right derivatives at a are equal','f''(a) is finite','f has a local extremum at a','A','Differentiability implies continuity, equality of one-sided derivatives, and a finite derivative; it does not imply an extremum.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39174,219,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M5','challenge','For integers nâ‰¥râ‰¥0, which identities are correct?','C(n,r)=C(n,n-r)','rÂ·C(n,r)=nÂ·C(n-1,r-1)','C(n,r)+C(n,r+1)=C(n+1,r+1)','P(n,r)=C(n,r)/r!','A','The first three are standard identities. P(n,r)=C(n,r)r!, not C(n,r)/r!.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39175,217,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M6','challenge','For the quadratic xÂ²-5x+6=0, which statements are correct?','Both roots are positive','Sum of roots is 5','Product of roots is 6','The discriminant is negative','A','The roots are 2 and 3, so the first three statements are true and the discriminant is positive.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39176,217,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M1','challenge','If the roots of xÂ²-9x+14=0 are Î± and Î², enter Î±Â²+Î²Â².','53','','','','A','(Î±+Î²)Â²-2Î±Î²=9Â²-2Ã—14=53.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39177,218,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M2','challenge','For A=[[2,1],[3,4]], enter det(AÂ²).','25','','','','A','det(A)=8-3=5 and det(AÂ²)=det(A)Â²=25.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39178,221,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M3','challenge','An AP has 5th term 18 and 11th term 42. Enter its common difference.','4','','','','A','The difference of the terms is 6d=42-18=24, hence d=4.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39179,222,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M4','challenge','Enter the value of lim(xâ†’0) [sin(5x)/x].','5','','','','A','sin(5x)/(5x)â†’1, so the limit is 5.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39180,219,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M5','challenge','Enter the number of diagonals in a convex 12-gon.','54','','','','A','The number of diagonals is n(n-3)/2=12Ã—9/2=54.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39181,218,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M6','challenge','If det(A)=3 for a 2Ã—2 matrix A, enter det(3Aâ»Â¹).','1.3333333333333333','','','','A','det(2Aâ»Â¹)=2Â² det(Aâ»Â¹)=4/3.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39182,231,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P1','challenge','A particle moves along x-axis with x=tÂ³-6tÂ²+9t. Its velocity is zero at t=1 s and:','2 s','3 s','4 s','6 s','B','v=3tÂ²-12t+9=3(t-1)(t-3), so the second instant is 3 s.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39183,232,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P2','challenge','A 5 kg block on a frictionless horizontal surface is pulled by 20 N. If a 3 kg block is attached to it and the same force pulls the pair, the acceleration becomes:','1.5 m/sÂ²','2.5 m/sÂ²','4 m/sÂ²','6.67 m/sÂ²','B','The total mass is 8 kg, so a=20/8=2.5 m/sÂ².',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39184,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P3','challenge','A spring of constant 200 N/m is compressed by 0.10 m. Its stored elastic potential energy is:','0.5 J','1 J','2 J','10 J','B','U=Â½kxÂ²=0.5Ã—200Ã—0.01=1 J.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39185,241,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P4','challenge','Two resistors 6 Î© and 3 Î© are connected in parallel across 12 V. The total current drawn is:','2 A','4 A','6 A','8 A','C','Equivalent resistance is 2 Î©, hence I=12/2=6 A.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39186,245,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P5','challenge','A thin convex lens has focal length 20 cm. An object is placed 60 cm in front of it. The magnitude of image distance is:','15 cm','20 cm','30 cm','60 cm','C','1/f=1/v+1/u in magnitudes gives 1/20=1/v+1/60, hence v=30 cm.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39187,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P6','challenge','A 2 kg body moving at 6 m/s is brought to rest uniformly over 3 m. The magnitude of the average retarding force is:','6 N','9 N','12 N','18 N','C','Work by the retarding force equals the loss of kinetic energy: FÃ—3=Â½Ã—2Ã—36=36, so F=12 N.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39188,231,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P1','challenge','For one-dimensional motion with constant acceleration, which relations are valid?','v=u+at','s=ut+Â½atÂ²','vÂ²=uÂ²+2as','s=(u+v)t for all such motion','A','The first three are standard equations. Average velocity is (u+v)/2, so s=(u+v)t/2.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39189,232,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P2','challenge','Which statements about Newton''s laws are correct in an inertial frame?','Net force equals rate of change of momentum','Action and reaction act on different bodies','If net force is zero, momentum is constant','A moving body must have a net force in the direction of motion','A','The first three are correct. Uniform motion needs no net force.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39190,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P3','challenge','Which quantities can be negative?','Work done by a force','Kinetic energy','Potential energy relative to a chosen zero','Power delivered by a force','A','Work, potential energy relative to a reference, and instantaneous power may be negative; kinetic energy is nonnegative.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39191,241,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P4','challenge','For resistors connected in parallel, which statements are correct?','Potential difference across each branch is the same','Equivalent resistance is less than the smallest branch resistance','Currents in all branches must be equal','Total current is the sum of branch currents','A','Parallel branches share the same voltage, equivalent resistance is smaller than any branch resistance, and currents add.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39192,245,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P5','challenge','For a real object in front of a concave mirror, which image types are possible as the object position changes?','Real inverted','Virtual erect','Magnified','Diminished','A','A concave mirror can produce all four descriptions depending on object position.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39193,241,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P6','challenge','For a metallic conductor obeying Ohm''s law at constant temperature, which statements are correct?','V is proportional to I','Resistance is V/I','Doubling V doubles I','Resistance necessarily doubles when V doubles','A','Ohm''s law gives V=IR with constant R; increasing V changes current, not the resistance under the stated condition.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39194,231,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P1','challenge','A particle starts from rest with constant acceleration 3 m/sÂ². Enter the distance travelled in the 4th second in metres.','10.5','','','','A','Distance in nth second is u+a(n-1/2)=0+3Ã—3.5=10.5 m.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39195,232,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P2','challenge','A 10 kg block has horizontal forces 35 N right and 15 N left. Enter its acceleration in m/sÂ².','2','','','','A','Net force is 20 N, so a=20/10=2 m/sÂ².',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39196,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P3','challenge','A 1000 kg car increases speed from 10 m/s to 20 m/s. Enter the increase in kinetic energy in kJ.','150','','','','A','Î”K=Â½m(vÂ²-uÂ²)=500(400-100)=150000 J=150 kJ.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39197,241,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P4','challenge','Three 6 Î© resistors are connected in parallel. Enter the equivalent resistance in ohms.','2','','','','A','For three equal resistors R in parallel, Req=R/3=2 Î©.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39198,245,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P5','challenge','A lens has power +5 dioptres. Enter its focal length in centimetres.','20','','','','A','f=1/P=0.2 m=20 cm.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39199,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P6','challenge','A machine does 18 kJ of work in 30 s. Enter its average power in watts.','600','','','','A','P=W/t=18000/30=600 W.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39200,250,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C1','challenge','How many moles of oxygen atoms are present in 0.5 mol of H2SO4?','0.5','1','2','4','C','Each mole of H2SO4 contains 4 mol of O atoms, so 0.5 mol contains 2 mol.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39201,255,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C2','challenge','For the equilibrium H2(g)+I2(g) â‡Œ 2HI(g), decreasing the volume at constant temperature ideally causes the equilibrium composition to:','shift right','shift left','remain unchanged','form only HI','C','The total number of gaseous moles is the same on both sides, so pressure/volume change does not shift the equilibrium.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39202,265,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C3','challenge','The coordination number of Co in [Co(NH3)6]3+ is:','3','4','6','9','C','Six monodentate NH3 ligands are directly coordinated to Co.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39203,264,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C4','challenge','Which ion has a d5 configuration?','Fe3+','Cu2+','Zn2+','Sc3+','A','Fe is [Ar]3d6 4s2; Fe3+ is [Ar]3d5.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39204,258,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C5','challenge','The number of atoms effectively present in one face-centered cubic unit cell is:','2','3','4','6','C','Eight corners contribute 1 atom and six faces contribute 3 atoms, total 4.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39205,255,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C6','challenge','At 25Â°C, a solution with [H+]=10^-3 M has pH:','1','2','3','11','C','pH=-log10(10^-3)=3.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39206,250,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_MS_C1','challenge','Which statements about one mole are correct?','It contains Avogadro''s number of specified entities','One mole of ideal gas always occupies 22.4 L at every temperature and pressure','Molar mass in grams is numerically equal to relative molecular mass','0.5 mol contains half Avogadro''s number of entities','A','Avogadro count and molar-mass relations are correct; 22.4 L applies only approximately under specific standard conditions.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39207,255,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_MS_C2','challenge','For a system at chemical equilibrium, which statements are correct?','Forward and reverse reaction rates are equal','Macroscopic concentrations remain constant with time','Both reactions stop','A catalyst changes the equilibrium constant','A','Equilibrium is dynamic: rates are equal and macroscopic concentrations are constant. Reactions continue, and a catalyst does not change K.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39208,265,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_MS_C3','challenge','Which can act as ligands through a lone pair?','NH3','H2O','CN-','Na+','A','NH3, H2O and CN- donate lone pairs; Na+ is not a ligand donor.',1,'jee-mock-advanced-v1','2026-09-02 21:33:36','2026-09-02 21:33:36');
