INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(40995,362,'US_PROGRAM_GRE_VERBAL_TEXT_COMPLETION_SINGLE_BLANK_002','medium','Because the witness had repeatedly changed her account, the jury viewed her testimony with considerable ______.','skepticism','delight','certainty','reverence','A','Repeatedly changing an account naturally leads to skepticism.',1,'gre-starter-v1','2026-09-07 00:21:50','2026-09-07 00:21:50');
