INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(43271,282,'IN_PROGRAM_NEET_PHYSICS_PROPERTIES_OF_SOLIDS_LIQUIDS_008','easy','Young''s modulus is defined as the ratio of:','longitudinal stress to longitudinal strain','shear stress to shear strain only','pressure to volume','force to area only','A','Young''s modulus relates normal stress to longitudinal strain within the elastic limit.',1,'neet-2026-quality-v2','2026-09-08 00:29:54','2026-09-08 00:29:54');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(43272,282,'IN_PROGRAM_NEET_PHYSICS_PROPERTIES_OF_SOLIDS_LIQUIDS_009','easy','The SI unit of surface tension is:','N m^-1','N m','Pa m','J m^-2 only','A','Surface tension is force per unit length, N/m.',1,'neet-2026-quality-v2','2026-09-08 00:29:54','2026-09-08 00:29:54');
