INSERT INTO "education_sat_question_details" ("question_id","response_type","stimulus_type","stimulus_text","stimulus_secondary_text","stimulus_data_json","accepted_answers_json","module_number","module_path","calculator_allowed","contextual","created_at","updated_at") VALUES(39548,'MCQ','TEXT','Researchers studying city neighborhoods have found that tree canopies can lower surface temperatures, capture some airborne particles, and slow storm-water runoff. These benefits vary by species and location, but together they can improve urban environmental conditions.',NULL,NULL,NULL,NULL,NULL,1,1,'2026-09-04 21:32:49','2026-09-04 21:32:49');
INSERT INTO "education_sat_question_details" ("question_id","response_type","stimulus_type","stimulus_text","stimulus_secondary_text","stimulus_data_json","accepted_answers_json","module_number","module_path","calculator_allowed","contextual","created_at","updated_at") VALUES(39549,'MCQ','TEXT','A team measured water quality at the same six stream sites in spring, summer, autumn, and winter. By repeating the measurements, the team could account for seasonal changes that might otherwise distort comparisons among the sites.',NULL,NULL,NULL,NULL,NULL,1,1,'2026-09-04 21:32:49','2026-09-04 21:32:49');
INSERT INTO "education_sat_question_details" ("question_id","response_type","stimulus_type","stimulus_text","stimulus_secondary_text","stimulus_data_json","accepted_answers_json","module_number","module_path","calculator_allowed","contextual","created_at","updated_at") VALUES(39550,'MCQ','TEXT','After a photography exhibition attracted more visitors than expected, the museum created an online version of the exhibition and extended gallery hours on two evenings each week.',NULL,NULL,NULL,NULL,NULL,1,1,'2026-09-04 21:32:49','2026-09-04 21:32:49');
INSERT INTO "education_sat_question_details" ("question_id","response_type","stimulus_type","stimulus_text","stimulus_secondary_text","stimulus_data_json","accepted_answers_json","module_number","module_path","calculator_allowed","contextual","created_at","updated_at") VALUES(39551,'MCQ','TEXT','Two sets of seeds were stored for six weeks. One set remained at room temperature; the other was refrigerated. When planted under the same conditions, 42% of the room-temperature seeds germinated, compared with 71% of the refrigerated seeds.',NULL,NULL,NULL,NULL,NULL,1,1,'2026-09-04 21:32:49','2026-09-04 21:32:49');
INSERT INTO "education_sat_question_details" ("question_id","response_type","stimulus_type","stimulus_text","stimulus_secondary_text","stimulus_data_json","accepted_answers_json","module_number","module_path","calculator_allowed","contextual","created_at","updated_at") VALUES(39552,'MCQ','TEXT','The island birds usually eat small, soft seeds. During unusually dry years, those seeds become scarce, and the birds shift to larger, harder seeds. Researchers have observed this pattern during several droughts.',NULL,NULL,NULL,NULL,NULL,1,1,'2026-09-04 21:32:49','2026-09-04 21:32:49');
