INSERT INTO "education_question_response_details" ("question_id","response_type","stimulus_type","stimulus_text","directions_text","choices_json","correct_answers_json","blank_count","numeric_tolerance","calculator_allowed","created_at","updated_at") VALUES(41252,'READING_COMPREHENSION','PASSAGE','Cities often respond to hotter summers by planting more trees. The policy is attractive because tree canopy can lower surface temperatures, absorb storm water, and improve neighborhood air quality. Yet citywide planting targets can conceal an important limitation: young trees provide little shade for years, and survival rates vary sharply with soil quality, irrigation, and maintenance. A program measured only by the number of trees planted may therefore appear successful while producing little cooling where heat exposure is greatest.',NULL,'["Tree planting is too expensive for most cities.","Tree-planting programs should be evaluated by outcomes, not planting totals alone.","Young trees should never be planted in hot neighborhoods.","Storm-water control is the primary benefit of urban trees.","Soil quality is more important than irrigation in every city."]','["B"]',0,NULL,0,'2026-09-07 04:26:24','2026-09-07 04:26:24');
INSERT INTO "education_question_response_details" ("question_id","response_type","stimulus_type","stimulus_text","directions_text","choices_json","correct_answers_json","blank_count","numeric_tolerance","calculator_allowed","created_at","updated_at") VALUES(41253,'READING_COMPREHENSION','PASSAGE','Cities often respond to hotter summers by planting more trees. The policy is attractive because tree canopy can lower surface temperatures, absorb storm water, and improve neighborhood air quality. Yet citywide planting targets can conceal an important limitation: young trees provide little shade for years, and survival rates vary sharply with soil quality, irrigation, and maintenance. A program measured only by the number of trees planted may therefore appear successful while producing little cooling where heat exposure is greatest.',NULL,'["residents in hotter neighborhoods generally oppose tree planting","surface temperature is unrelated to tree survival","local growing conditions and maintenance can differ","mature trees absorb less storm water than young trees","citywide planting targets require identical species"]','["C"]',0,NULL,0,'2026-09-07 04:26:24','2026-09-07 04:26:24');
INSERT INTO "education_question_response_details" ("question_id","response_type","stimulus_type","stimulus_text","directions_text","choices_json","correct_answers_json","blank_count","numeric_tolerance","calculator_allowed","created_at","updated_at") VALUES(41255,'TEXT_COMPLETION','NONE',NULL,NULL,'["accessible","cryptic","partisan","tentative","derivative"]','["A"]',1,NULL,0,'2026-09-07 04:26:24','2026-09-07 04:26:24');
