PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE shops (
  code TEXT PRIMARY KEY
    CHECK(length(code) = 4),

  name TEXT NOT NULL,
  owner_name TEXT NOT NULL,

  phone_number TEXT NOT NULL,
  whatsapp_number TEXT,
  email_address TEXT,

  address_line TEXT NOT NULL,
  city TEXT NOT NULL,
  state TEXT NOT NULL,
  postal_code TEXT NOT NULL,

  status TEXT NOT NULL DEFAULT 'active'
    CHECK(status IN ('pending', 'active', 'suspended')),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, latitude REAL
CHECK (
  latitude IS NULL OR
  (latitude >= -90 AND latitude <= 90)
), longitude REAL
CHECK (
  longitude IS NULL OR
  (longitude >= -180 AND longitude <= 180)
));
CREATE TABLE services (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_code TEXT NOT NULL UNIQUE,
  service_type TEXT NOT NULL DEFAULT 'system'
    CHECK(service_type IN ('system', 'custom')),

  category TEXT NOT NULL,
  sub_category TEXT,

  name TEXT NOT NULL,
  description TEXT,

  icon TEXT,
  color TEXT,

  workflow_type TEXT NOT NULL DEFAULT 'generic'
    CHECK(
      workflow_type IN (
        'print',
        'upload',
        'assistance',
        'appointment',
        'payment',
        'generic'
      )
    ),

  
  owner_shop_code TEXT,

  enabled INTEGER NOT NULL DEFAULT 1
    CHECK(enabled IN (0, 1)),

  sort_order INTEGER NOT NULL DEFAULT 0,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, homepage_order INTEGER
  CHECK (
    homepage_order IS NULL OR
    homepage_order >= 0
  ),

  FOREIGN KEY(owner_shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE
);
CREATE TABLE shop_services (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  shop_code TEXT NOT NULL,
  service_id INTEGER NOT NULL,

  enabled INTEGER NOT NULL DEFAULT 0
    CHECK(enabled IN (0, 1)),

  display_name TEXT,
  description_override TEXT,
  icon_override TEXT,
  color_override TEXT,

  price_type TEXT NOT NULL DEFAULT 'contact'
    CHECK(
      price_type IN (
        'fixed',
        'starting_at',
        'per_page',
        'quote',
        'free',
        'contact'
      )
    ),

  price_amount_paise INTEGER
    CHECK(
      price_amount_paise IS NULL OR
      price_amount_paise >= 0
    ),

  price_note TEXT,

  sort_order INTEGER NOT NULL DEFAULT 0,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, featured INTEGER NOT NULL DEFAULT 0,

  UNIQUE(shop_code, service_id),

  FOREIGN KEY(shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE,

  FOREIGN KEY(service_id)
    REFERENCES services(id)
    ON DELETE CASCADE
);
CREATE TABLE admin_login_codes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  email TEXT NOT NULL,
  code_hash TEXT NOT NULL,

  request_ip TEXT,

  expires_at TEXT NOT NULL,
  used_at TEXT,

  attempt_count INTEGER NOT NULL DEFAULT 0,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admin_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  email TEXT NOT NULL,
  session_hash TEXT NOT NULL UNIQUE,

  expires_at TEXT NOT NULL,
  revoked_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE print_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  order_number TEXT NOT NULL UNIQUE,

  shop_code TEXT NOT NULL,

  customer_name TEXT NOT NULL,
  phone_number TEXT NOT NULL,
  email_address TEXT,
  whatsapp_number TEXT,
  whatsapp_consent INTEGER NOT NULL DEFAULT 0,

  estimated_pages INTEGER NOT NULL DEFAULT 1,
  copies INTEGER NOT NULL DEFAULT 1,

  color_mode TEXT NOT NULL,
  print_sides TEXT NOT NULL,
  paper_size TEXT NOT NULL,

  instructions TEXT,

  estimated_amount_rupees INTEGER,

  status TEXT NOT NULL DEFAULT 'submitted',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
);
CREATE TABLE print_request_files (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  print_request_id INTEGER NOT NULL,

  original_file_name TEXT NOT NULL,
  content_type TEXT,
  file_size INTEGER NOT NULL,

  storage_key TEXT,
  storage_status TEXT NOT NULL DEFAULT 'pending',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (print_request_id)
    REFERENCES print_requests(id)
    ON DELETE CASCADE
);
CREATE TABLE system_settings (
  setting_key TEXT PRIMARY KEY,
  setting_value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE service_sections (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_id INTEGER NOT NULL,

  section_key TEXT NOT NULL,
  label TEXT NOT NULL,

  description TEXT,

  visibility TEXT NOT NULL DEFAULT 'visible'
    CHECK (
      visibility IN (
        'visible',
        'hidden'
      )
    ),

  include_in_shop_email INTEGER NOT NULL DEFAULT 1,
  include_in_customer_email INTEGER NOT NULL DEFAULT 1,

  sort_order INTEGER NOT NULL DEFAULT 10,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (service_id)
    REFERENCES services(id)
    ON DELETE CASCADE,

  UNIQUE (
    service_id,
    section_key
  )
);
CREATE TABLE service_fields (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  section_id INTEGER NOT NULL,

  field_key TEXT NOT NULL,
  label TEXT NOT NULL,

  field_type TEXT NOT NULL
    CHECK (
      field_type IN (
        'text',
        'textarea',
        'number',
        'email',
        'tel',
        'date',
        'select',
        'radio',
        'checkbox',
        'checkbox-group',
        'file'
      )
    ),

  requirement TEXT NOT NULL DEFAULT 'optional'
    CHECK (
      requirement IN (
        'mandatory',
        'optional',
        'hidden'
      )
    ),

  placeholder TEXT,
  help_text TEXT,

  default_value TEXT,

  options_json TEXT,
  validation_json TEXT,

  email_label TEXT,

  include_in_shop_email INTEGER NOT NULL DEFAULT 1,
  include_in_customer_email INTEGER NOT NULL DEFAULT 1,
  include_in_request_view INTEGER NOT NULL DEFAULT 1,

  sort_order INTEGER NOT NULL DEFAULT 10,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (section_id)
    REFERENCES service_sections(id)
    ON DELETE CASCADE,

  UNIQUE (
    section_id,
    field_key
  )
);
CREATE TABLE service_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  request_number TEXT NOT NULL UNIQUE,

  shop_code TEXT NOT NULL,
  service_id INTEGER NOT NULL,

  customer_name TEXT,
  phone_number TEXT,
  email_address TEXT,
  whatsapp_number TEXT,
  whatsapp_consent INTEGER NOT NULL DEFAULT 0,

  status TEXT NOT NULL DEFAULT 'submitted',

  details_json TEXT NOT NULL DEFAULT '{}',

  estimated_amount_paise INTEGER,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, gyan_account_id INTEGER,

  FOREIGN KEY (shop_code)
    REFERENCES shops(code),

  FOREIGN KEY (service_id)
    REFERENCES services(id)
);
CREATE TABLE service_request_files (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_request_id INTEGER NOT NULL,

  section_key TEXT NOT NULL,
  field_key TEXT NOT NULL,

  original_file_name TEXT NOT NULL,
  content_type TEXT NOT NULL,
  file_size INTEGER NOT NULL,

  storage_key TEXT NOT NULL UNIQUE,
  storage_status TEXT NOT NULL DEFAULT 'stored',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (service_request_id)
    REFERENCES service_requests(id)
    ON DELETE CASCADE
);
CREATE TABLE service_market_prices (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_id INTEGER NOT NULL,

  country_code TEXT NOT NULL,
  currency_code TEXT NOT NULL,

  price_type TEXT NOT NULL DEFAULT 'starting_at'
    CHECK (
      price_type IN (
        'fixed',
        'starting_at',
        'per_page',
        'quote',
        'free',
        'contact'
      )
    ),

  amount_minor INTEGER
    CHECK (
      amount_minor IS NULL OR
      amount_minor >= 0
    ),

  price_note TEXT,

  enabled INTEGER NOT NULL DEFAULT 1
    CHECK (enabled IN (0, 1)),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (service_id)
    REFERENCES services(id)
    ON DELETE CASCADE,

  UNIQUE(service_id, country_code)
);
CREATE TABLE daily_puzzles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  puzzle_date TEXT NOT NULL,
  puzzle_number INTEGER NOT NULL,

  stage TEXT NOT NULL
    CHECK (
      stage IN (
        '5x5',
        '7x7'
      )
    ),

  board_size INTEGER NOT NULL,
  max_moves INTEGER NOT NULL,
  mystery_count INTEGER NOT NULL,

  
  start_board_json TEXT NOT NULL,

  
  solved_board_json TEXT NOT NULL,

  
  solution_moves_json TEXT NOT NULL,

  
  mystery_reveal_order_json TEXT NOT NULL,

  verified INTEGER
    NOT NULL
    DEFAULT 0,

  status TEXT
    NOT NULL
    DEFAULT 'draft'
    CHECK (
      status IN (
        'draft',
        'published',
        'retired'
      )
    ),

  created_at TEXT
    NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT
    NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    puzzle_date,
    stage
  ),

  UNIQUE (
    puzzle_number,
    stage
  )
);
CREATE TABLE puzzle_winners (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  puzzle_number INTEGER NOT NULL,
  puzzle_date TEXT NOT NULL,

  name TEXT NOT NULL,
  email TEXT NOT NULL,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    puzzle_number,
    email
  )
);
CREATE TABLE featured_promotions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  source_type TEXT NOT NULL
    CHECK (
      source_type IN (
        'gyan',
        'groupon',
        'woot',
        'affiliate',
        'default'
      )
    ),

  title TEXT NOT NULL,
  description TEXT,

  icon TEXT,
  image_url TEXT,

  cta_label TEXT NOT NULL DEFAULT 'View',

  target_url TEXT,

  service_code TEXT,
  shop_code TEXT,

  latitude REAL,
  longitude REAL,
  radius_km REAL,

  starts_at TEXT,
  ends_at TEXT,

  priority INTEGER NOT NULL DEFAULT 0,

  enabled INTEGER NOT NULL DEFAULT 1,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, offer_text TEXT, discount_percent REAL);
CREATE TABLE advertisement_submissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  status TEXT NOT NULL DEFAULT 'pending_email_verification'
    CHECK (
      status IN (
        'pending_email_verification',
        'pending_review',
        'approved',
        'rejected'
      )
    ),

  business_name TEXT NOT NULL,
  service_name TEXT NOT NULL,

  offer_text TEXT,
  discount_percent REAL,

  latitude REAL NOT NULL,
  longitude REAL NOT NULL,

  service_radius_km REAL NOT NULL,

  phone TEXT NOT NULL,
  email TEXT NOT NULL,

  verification_token_hash TEXT,
  verification_expires_at TEXT,

  email_verified_at TEXT,
  approved_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, admin_review_token_hash TEXT, admin_review_expires_at TEXT, duration_days INTEGER NOT NULL DEFAULT 7, description TEXT, featured_promotion_id INTEGER, delete_token_hash TEXT, delete_token_expires_at TEXT, deleted_at TEXT, city TEXT, region TEXT, region_code TEXT, country_code TEXT, postal_code TEXT);
CREATE TABLE local_service_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  status TEXT NOT NULL DEFAULT 'pending_email_verification',

  service_name TEXT NOT NULL,

  details TEXT,

  latitude REAL NOT NULL,
  longitude REAL NOT NULL,

  search_radius_km REAL NOT NULL,

  email TEXT NOT NULL,
  phone TEXT,

  preferred_time TEXT,

  verification_token_hash TEXT,
  verification_expires_at TEXT,

  email_verified_at TEXT,

  assigned_shop_code TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, city TEXT, region TEXT, region_code TEXT, country_code TEXT, postal_code TEXT);
CREATE TABLE daily_analytics (
  analytics_date TEXT NOT NULL,
  country_code TEXT NOT NULL DEFAULT '',
  region TEXT NOT NULL DEFAULT '',
  city TEXT NOT NULL DEFAULT '',
  latitude REAL,
  longitude REAL,
  unique_visitors INTEGER NOT NULL DEFAULT 0,
  visits INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (analytics_date, country_code, region, city)
);
CREATE TABLE daily_analytics_visitors (
  analytics_date TEXT NOT NULL,
  visitor_hash TEXT NOT NULL,
  country_code TEXT NOT NULL DEFAULT '',
  region TEXT NOT NULL DEFAULT '',
  city TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (analytics_date, visitor_hash)
);
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_login_at TEXT
, last_city TEXT, last_region TEXT, last_region_code TEXT, last_country_code TEXT, last_postal_code TEXT, last_location_at TEXT);
CREATE TABLE auth_magic_links (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, return_path TEXT, return_to TEXT);
CREATE TABLE user_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE TABLE chat_threads (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  request_id INTEGER NOT NULL UNIQUE,
  customer_user_id INTEGER,
  shop_code TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (request_id) REFERENCES service_requests(id),
  FOREIGN KEY (customer_user_id) REFERENCES users(id)
);
CREATE TABLE chat_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  thread_id INTEGER NOT NULL,
  sender_type TEXT NOT NULL,
  sender_user_id INTEGER,
  sender_shop_code TEXT,
  message TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (thread_id) REFERENCES chat_threads(id),
  FOREIGN KEY (sender_user_id) REFERENCES users(id)
);
CREATE TABLE offline_shop_codes (
  code TEXT PRIMARY KEY,
  status TEXT NOT NULL DEFAULT 'reserved'
    CHECK (status IN ('reserved','claimed')),
  batch_code TEXT NOT NULL,
  claimed_shop_code TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  claimed_at TEXT,
  CHECK (length(code)=4),
  CHECK (substr(code,3,1)='R')
);
CREATE TABLE shop_featured_services (
  shop_code TEXT NOT NULL,
  service_id INTEGER NOT NULL,
  featured_order INTEGER NOT NULL
    CHECK (featured_order BETWEEN 1 AND 3),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (shop_code, service_id),
  UNIQUE (shop_code, featured_order),

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE,

  FOREIGN KEY (service_id)
    REFERENCES services(id)
    ON DELETE CASCADE
);
CREATE TABLE anonymous_request_usage (
  shop_code TEXT NOT NULL,
  usage_date TEXT NOT NULL,
  request_count INTEGER NOT NULL DEFAULT 0
    CHECK (request_count >= 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (
    shop_code,
    usage_date
  ),

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE
);
CREATE TABLE request_guard_alerts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  shop_code TEXT NOT NULL,
  alert_key TEXT NOT NULL,
  alert_scope TEXT NOT NULL
    CHECK (
      alert_scope IN (
        'day',
        'month'
      )
    ),
  period_key TEXT NOT NULL,
  request_count INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    shop_code,
    alert_key,
    period_key
  ),

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE
);
CREATE TABLE puzzle_results (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  result_id TEXT NOT NULL,

  puzzle_number INTEGER NOT NULL,
  puzzle_date TEXT NOT NULL,
  stage TEXT NOT NULL
    CHECK (
      stage IN (
        '5x5',
        '7x7'
      )
    ),

  gq_score INTEGER NOT NULL,
  moves_used INTEGER NOT NULL,

  icons_json TEXT NOT NULL
    DEFAULT '[]',

  skill_stats_json TEXT NOT NULL
    DEFAULT '{}',

  name TEXT,
  email TEXT,

  claimed INTEGER NOT NULL
    DEFAULT 0
    CHECK (
      claimed IN (
        0,
        1
      )
    ),

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP, gyan_account_id INTEGER,

  UNIQUE (
    puzzle_number,
    stage,
    result_id
  )
);
CREATE TABLE puzzle_guest_names (
  puzzle_number INTEGER NOT NULL,
  result_id TEXT NOT NULL,
  guest_name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (puzzle_number, result_id),
  UNIQUE (puzzle_number, guest_name)
);
CREATE TABLE student_invite_codes (
  code TEXT PRIMARY KEY,

  country_code TEXT NOT NULL,

  print_format TEXT NOT NULL
    CHECK (
      print_format IN (
        'A5',
        'A6',
        'A7',
        'A8',
        'CREDIT_CARD',
        'BUSINESS_CARD'
      )
    ),

  orientation TEXT NOT NULL
    CHECK (
      orientation IN (
        'portrait',
        'landscape'
      )
    ),

  range_start TEXT NOT NULL,
  range_end TEXT NOT NULL,

  status TEXT NOT NULL
    DEFAULT 'active'
    CHECK (
      status IN (
        'active',
        'disabled'
      )
    ),

  scan_count INTEGER NOT NULL
    DEFAULT 0,

  registration_count INTEGER NOT NULL
    DEFAULT 0,

  first_scanned_at TEXT,
  last_scanned_at TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  CHECK (
    length(code) = 4
  )
);
CREATE TABLE education_country_settings (
  country_code TEXT PRIMARY KEY
    CHECK (country_code IN ('US', 'IN')),

  prek12_enabled INTEGER NOT NULL DEFAULT 1
    CHECK (prek12_enabled IN (0, 1)),

  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE education_programs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  country_code TEXT NOT NULL
    CHECK (country_code IN ('US', 'IN')),

  program_code TEXT NOT NULL,
  program_name TEXT NOT NULL,

  enabled INTEGER NOT NULL DEFAULT 1
    CHECK (enabled IN (0, 1)),

  is_custom INTEGER NOT NULL DEFAULT 0
    CHECK (is_custom IN (0, 1)),

  sort_order INTEGER NOT NULL DEFAULT 100,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  UNIQUE(country_code, program_code),

  FOREIGN KEY(country_code)
    REFERENCES education_country_settings(country_code)
    ON DELETE CASCADE
);
CREATE TABLE education_subjects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  country_code TEXT NOT NULL,
  grade_code TEXT NOT NULL,
  subject_code TEXT NOT NULL,
  subject_name TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  sort_order INTEGER NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(country_code, grade_code, subject_code)
);
CREATE TABLE education_topics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  subject_id INTEGER NOT NULL,
  topic_code TEXT NOT NULL,
  topic_name TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  sort_order INTEGER NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(subject_id, topic_code),
  FOREIGN KEY(subject_id)
    REFERENCES education_subjects(id)
    ON DELETE CASCADE
);
CREATE TABLE education_subtopics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  topic_id INTEGER NOT NULL,
  subtopic_code TEXT NOT NULL,
  subtopic_name TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  sort_order INTEGER NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(topic_id, subtopic_code),
  FOREIGN KEY(topic_id)
    REFERENCES education_topics(id)
    ON DELETE CASCADE
);
CREATE TABLE education_questions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  subtopic_id INTEGER NOT NULL,
  question_key TEXT NOT NULL UNIQUE,
  difficulty TEXT NOT NULL
    CHECK (difficulty IN ('easy','medium','challenge')),
  question_text TEXT NOT NULL,
  choice_a TEXT NOT NULL,
  choice_b TEXT NOT NULL,
  choice_c TEXT NOT NULL,
  choice_d TEXT NOT NULL,
  correct_choice TEXT NOT NULL
    CHECK (correct_choice IN ('A','B','C','D')),
  explanation TEXT NOT NULL DEFAULT '',
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  source_type TEXT NOT NULL DEFAULT 'generated',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(subtopic_id)
    REFERENCES education_subtopics(id)
    ON DELETE CASCADE
);
CREATE TABLE education_students (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  student_code TEXT NOT NULL UNIQUE,
  student_name TEXT NOT NULL,

  email TEXT NOT NULL,
  user_id INTEGER,

  country_code TEXT NOT NULL,
  grade_code TEXT NOT NULL,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, gyan_account_id INTEGER,

  FOREIGN KEY(user_id)
    REFERENCES users(id)
    ON DELETE SET NULL
);
CREATE TABLE calendar_access_codes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  slug TEXT NOT NULL UNIQUE,
  gyan_name TEXT NOT NULL UNIQUE,
  access_code TEXT NOT NULL UNIQUE,

  qr_token_hash TEXT UNIQUE,

  duration_months INTEGER NOT NULL
    CHECK (
      duration_months IN (
        1,
        3,
        6,
        12
      )
    ),

  welcome_gems INTEGER NOT NULL DEFAULT 0,

  artwork_key TEXT NOT NULL DEFAULT 'GODDESS'
    CHECK (
      artwork_key IN (
        'GODDESS',
        'EDUCATION',
        'SCENIC'
      )
    ),

  status TEXT NOT NULL DEFAULT 'GENERATED'
    CHECK (
      status IN (
        'GENERATED',
        'PRINTED',
        'GUEST_ACTIVE',
        'CLAIMED',
        'EXPIRED'
      )
    ),

  email TEXT,

  generated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  printed_at TEXT,

  guest_started_at TEXT,
  guest_expires_at TEXT,

  claimed_at TEXT,
  expires_at TEXT,

  source TEXT NOT NULL DEFAULT 'CALENDAR',
  created_by_email TEXT
);
CREATE TABLE calendar_guest_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  calendar_access_id INTEGER NOT NULL,

  token_hash TEXT NOT NULL UNIQUE,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at TEXT NOT NULL,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
    ON DELETE CASCADE
);
CREATE TABLE gem_transactions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  calendar_access_id INTEGER NOT NULL,

  amount INTEGER NOT NULL,

  reason TEXT NOT NULL,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
    ON DELETE CASCADE,

  UNIQUE (
    calendar_access_id,
    reason
  )
);
CREATE TABLE gyan_lost_found_profiles (
  safety_resource_id INTEGER PRIMARY KEY,

  owner_deliver_at TEXT,
  owner_contact TEXT,
  owner_message TEXT,

  finder_found_at TEXT,
  finder_will_deliver_at TEXT,
  finder_message TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP, support_requested INTEGER NOT NULL
DEFAULT 0
CHECK (
  support_requested IN (
    0,
    1
  )
),

  FOREIGN KEY (
    safety_resource_id
  )
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_lost_found_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  safety_resource_id INTEGER NOT NULL,

  sender_role TEXT NOT NULL
    CHECK (
      sender_role IN (
        'FINDER',
        'OWNER',
        'SUPPORT'
      )
    ),

  message TEXT NOT NULL,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (
    safety_resource_id
  )
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_emergency_profiles (
  safety_resource_id INTEGER PRIMARY KEY,

  emergency_message TEXT,
  primary_contact TEXT,
  secondary_contact TEXT,
  medical_notes TEXT,
  meeting_place TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (
    safety_resource_id
  )
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_emergency_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  safety_resource_id INTEGER NOT NULL,

  message TEXT NOT NULL,

  contact TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (
    safety_resource_id
  )
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "gyan_safety_resources" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  calendar_access_id INTEGER NOT NULL,

  resource_type TEXT NOT NULL
    CHECK (
      resource_type IN (
        'MESSAGE',
        'CERTIFICATE',
        'LOST_FOUND',
        'EMERGENCY',
        'HELP'
      )
    ),

  public_token TEXT NOT NULL UNIQUE,

  status TEXT NOT NULL DEFAULT 'ACTIVE'
    CHECK (
      status IN (
        'ACTIVE',
        'REVOKED'
      )
    ),

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  revoked_at TEXT,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
    ON DELETE CASCADE,

  UNIQUE (
    calendar_access_id,
    resource_type
  )
);
CREATE TABLE gyan_account_calendar_links (
  gyan_account_id INTEGER NOT NULL UNIQUE,

  calendar_access_id INTEGER NOT NULL UNIQUE,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (gyan_account_id)

-- MOVED EARLIER FOR LOCAL D1 RESTORE
