, created_city TEXT, created_region TEXT, created_region_code TEXT, created_country TEXT, created_country_code TEXT, created_timezone TEXT, created_device_type TEXT, created_os TEXT, created_os_version TEXT, created_browser TEXT, created_browser_version TEXT, created_screen_width INTEGER, created_screen_height INTEGER, created_viewport_width INTEGER, created_viewport_height INTEGER, created_touch INTEGER NOT NULL DEFAULT 0, created_language TEXT, created_languages TEXT, created_platform TEXT, created_referrer TEXT, created_utm_source TEXT, created_utm_medium TEXT, created_utm_campaign TEXT);
-- END MOVED gyan_accounts BLOCK

    REFERENCES gyan_accounts(id)
    ON DELETE CASCADE,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
