CREATE TABLE gyan_recovery_emails (
  calendar_access_id INTEGER PRIMARY KEY,

  email TEXT NOT NULL,

  verified INTEGER NOT NULL
    DEFAULT 0
    CHECK (verified IN (0, 1)),

  verification_token_hash TEXT,

  verification_expires_at TEXT,

  verified_at TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_winks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  safety_resource_id INTEGER NOT NULL,

  wink_token TEXT NOT NULL UNIQUE,

  kind TEXT NOT NULL DEFAULT 'ðŸ˜‰',

  message TEXT NOT NULL,

  recipient_query TEXT,

  add_friend INTEGER NOT NULL DEFAULT 0
    CHECK (add_friend IN (0, 1)),

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP, sender_account_id INTEGER
REFERENCES gyan_accounts(id)
ON DELETE SET NULL, recipient_account_id INTEGER
REFERENCES gyan_accounts(id)
ON DELETE SET NULL, parent_wink_id INTEGER
REFERENCES gyan_winks(id)
ON DELETE SET NULL, read_at TEXT, expires_at TEXT,

  FOREIGN KEY (safety_resource_id)
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_browser_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  account_id INTEGER NOT NULL,
  secret_hash TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (account_id) REFERENCES gyan_accounts(id) ON DELETE CASCADE
);
CREATE TABLE gyan_account_aliases (
  alias_code TEXT PRIMARY KEY,
  account_id INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (account_id) REFERENCES gyan_accounts(id) ON DELETE CASCADE
);
CREATE TABLE class_teachers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  display_name TEXT NOT NULL,
  education TEXT NOT NULL DEFAULT '',
  experience TEXT NOT NULL DEFAULT '',
  level TEXT NOT NULL CHECK (level IN ('BRONZE','SILVER','GOLD')),
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE class_offerings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  category TEXT NOT NULL CHECK (category IN ('IIT-JEE','NEET')),
  subject TEXT NOT NULL,
  topic TEXT NOT NULL,
  teacher_id INTEGER NOT NULL,
  class_type TEXT NOT NULL CHECK (class_type IN ('DEMO','ACTUAL')),
  weekday INTEGER NOT NULL CHECK (weekday BETWEEN 1 AND 7),
  start_ist TEXT NOT NULL,
  duration_minutes INTEGER NOT NULL CHECK (duration_minutes IN (30,60)),
  program_start_date TEXT NOT NULL,
  program_end_date TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (teacher_id) REFERENCES class_teachers(id)
);
CREATE TABLE class_registrations (
  id TEXT PRIMARY KEY,
  offering_id INTEGER NOT NULL,
  occurrence_date TEXT NOT NULL,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'REGISTERED',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (offering_id) REFERENCES class_offerings(id)
);
CREATE TABLE education_little_questions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  skill_code TEXT NOT NULL,
  level INTEGER NOT NULL DEFAULT 1,

  prompt_text TEXT NOT NULL,

  question_type TEXT NOT NULL
    CHECK (
      question_type IN (
        'tap',
        'speak'
      )
    ),

  option_a TEXT,
  option_b TEXT,
  option_c TEXT,

  correct_option TEXT
    CHECK (
      correct_option IS NULL OR
      correct_option IN ('A','B','C')
    ),

  accepted_words TEXT,

  active INTEGER NOT NULL DEFAULT 1
    CHECK (active IN (0,1)),

  sort_order INTEGER NOT NULL DEFAULT 100,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, topic_code TEXT, topic_name TEXT, subtopic_code TEXT, subtopic_name TEXT, icon_hint TEXT, visual_type TEXT, visual_object TEXT, option_a_scale TEXT, option_b_scale TEXT, option_c_scale TEXT,

  UNIQUE(
    skill_code,
    level,
    prompt_text,
    option_a,
    option_b,
    option_c
  )
);
CREATE TABLE education_child_words (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  student_id INTEGER NOT NULL,

  word TEXT NOT NULL,
  normalized_word TEXT NOT NULL,

  status TEXT NOT NULL
    CHECK (
      status IN (
        'emerging',
        'independent'
      )
    ),

  first_observed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  first_independent_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE,

  UNIQUE(
    student_id,
    normalized_word
  )
);
CREATE TABLE education_little_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  student_id INTEGER,

  question_id INTEGER NOT NULL,

  response_type TEXT NOT NULL
    CHECK (
      response_type IN (
        'tap',
        'speech',
        'parent'
      )
    ),

  response_value TEXT,

  correct INTEGER NOT NULL
    CHECK (correct IN (0,1)),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE SET NULL,

  FOREIGN KEY(question_id)
    REFERENCES education_little_questions(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_account_email_verifications (
  account_id INTEGER PRIMARY KEY,
  email TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  verified_at TEXT,
  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (account_id)
    REFERENCES gyan_accounts(id)
    ON DELETE CASCADE
);
CREATE TABLE education_mock_tests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  program_code TEXT NOT NULL,
  test_kind TEXT NOT NULL
    CHECK (test_kind IN ('FULL','MINI')),
  test_code TEXT NOT NULL,
  test_name TEXT NOT NULL,
  exam_level TEXT NOT NULL
    CHECK (exam_level IN ('MAIN','ADVANCED','NEET')),
  version INTEGER NOT NULL DEFAULT 1,
  access_mode TEXT NOT NULL DEFAULT 'LOCKED'
    CHECK (access_mode IN ('OPEN','CODE','LOCKED')),
  published INTEGER NOT NULL DEFAULT 0
    CHECK (published IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (
    program_code,
    test_kind,
    test_code,
    exam_level,
    version
  )
);
CREATE TABLE education_mock_test_questions (
  mock_test_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  question_order INTEGER NOT NULL,
  section_code TEXT,
  marks_correct REAL,
  marks_incorrect REAL,
  marks_unanswered REAL NOT NULL DEFAULT 0,
  PRIMARY KEY (mock_test_id, question_order),
  UNIQUE (mock_test_id, question_id),
  FOREIGN KEY (mock_test_id)
    REFERENCES education_mock_tests(id)
    ON DELETE CASCADE,
  FOREIGN KEY (question_id)
    REFERENCES education_questions(id)
    ON DELETE RESTRICT
);
CREATE TABLE education_mock_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER,
  mock_test_id INTEGER NOT NULL,
  started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  submitted_at TEXT,
  score REAL,
  max_score REAL,
  correct_count INTEGER,
  incorrect_count INTEGER,
  unanswered_count INTEGER,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, attempt_number INTEGER, elapsed_seconds INTEGER NOT NULL DEFAULT 0, save_count INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (student_id)
    REFERENCES education_students(id)
    ON DELETE SET NULL,
  FOREIGN KEY (mock_test_id)
    REFERENCES education_mock_tests(id)
    ON DELETE RESTRICT
);
CREATE TABLE education_mock_attempt_answers (
  attempt_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  selected_answer TEXT,
  correct INTEGER
    CHECK (correct IS NULL OR correct IN (0,1)),
  marks_awarded REAL, marked_for_review INTEGER NOT NULL DEFAULT 0
  CHECK (marked_for_review IN (0,1)),
  PRIMARY KEY (attempt_id, question_id),
  FOREIGN KEY (attempt_id)
    REFERENCES education_mock_attempts(id)
    ON DELETE CASCADE,
  FOREIGN KEY (question_id)
    REFERENCES education_questions(id)
    ON DELETE RESTRICT
);
CREATE TABLE education_mock_question_answers (
  question_id INTEGER PRIMARY KEY,
  answer_key TEXT NOT NULL,
  FOREIGN KEY (question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
);
CREATE TABLE education_student_question_history (
  student_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  first_attempted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (
    student_id,
    question_id
  ),

  FOREIGN KEY (student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE,

  FOREIGN KEY (question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
) WITHOUT ROWID;
CREATE TABLE education_protection_milestones (
  student_id INTEGER PRIMARY KEY,

  milestone_25_shown INTEGER NOT NULL DEFAULT 0
    CHECK (milestone_25_shown IN (0,1)),

  milestone_50_shown INTEGER NOT NULL DEFAULT 0
    CHECK (milestone_50_shown IN (0,1)),

  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE
);
CREATE TABLE education_teachers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  gyan_account_id INTEGER,
  teacher_name TEXT NOT NULL,
  email TEXT NOT NULL COLLATE NOCASE,
  subjects TEXT NOT NULL DEFAULT '',
  location TEXT,
  bio TEXT,
  status TEXT NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING','APPROVED','INACTIVE')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(email),
  FOREIGN KEY (gyan_account_id)
    REFERENCES gyan_accounts(id)
    ON DELETE SET NULL
);
CREATE TABLE education_teacher_assignments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER NOT NULL,
  teacher_id INTEGER,
  status TEXT NOT NULL DEFAULT 'REQUESTED'
    CHECK (status IN ('REQUESTED','ASSIGNED','CLOSED')),
  requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  assigned_at TEXT,
  assigned_by_email TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, request_email TEXT, request_phone TEXT, request_subjects TEXT,
  FOREIGN KEY (student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE,
  FOREIGN KEY (teacher_id)
    REFERENCES education_teachers(id)
    ON DELETE SET NULL
);
CREATE TABLE education_countries (
  country_code TEXT PRIMARY KEY,
  country_name TEXT NOT NULL,
  flag_emoji TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE education_program_catalog (
  program_code TEXT PRIMARY KEY,
  canonical_name TEXT NOT NULL,

  
  grade_code TEXT NOT NULL,

  
  experience_type TEXT NOT NULL DEFAULT 'CBT',

  enabled INTEGER NOT NULL DEFAULT 1,

  show_questions INTEGER NOT NULL DEFAULT 1,
  show_mock_tests INTEGER NOT NULL DEFAULT 0,
  show_reports INTEGER NOT NULL DEFAULT 1,
  show_demo INTEGER NOT NULL DEFAULT 0,
  show_classes INTEGER NOT NULL DEFAULT 0,

  duration_minutes INTEGER,
  question_count INTEGER,

  correct_marks REAL,
  incorrect_marks REAL,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, question_palette_columns INTEGER NOT NULL DEFAULT 5, result_palette_columns INTEGER NOT NULL DEFAULT 5);
CREATE TABLE education_sat_question_details (
  question_id INTEGER PRIMARY KEY,

  response_type TEXT NOT NULL DEFAULT 'MCQ'
    CHECK (response_type IN ('MCQ','SPR')),

  stimulus_type TEXT NOT NULL DEFAULT 'NONE'
    CHECK (stimulus_type IN (
      'NONE',
      'TEXT',
      'PASSAGE_PAIR',
      'STUDENT_NOTES',
      'TABLE',
      'BAR_GRAPH',
      'LINE_GRAPH',
      'OTHER_GRAPHIC'
    )),

  stimulus_text TEXT,
  stimulus_secondary_text TEXT,

  
  stimulus_data_json TEXT,

  
  accepted_answers_json TEXT,

  
  module_number INTEGER
    CHECK (module_number IS NULL OR module_number IN (1,2)),

  module_path TEXT
    CHECK (
      module_path IS NULL OR
      module_path IN ('BASE','EASIER','HARDER')
    ),

  calculator_allowed INTEGER NOT NULL DEFAULT 1
    CHECK (calculator_allowed IN (0,1)),

  contextual INTEGER NOT NULL DEFAULT 0
    CHECK (contextual IN (0,1)),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
);
CREATE TABLE education_practice_cursors (
  gyan_account_id INTEGER NOT NULL,
  scope_key TEXT NOT NULL,

  last_subtopic_id INTEGER NOT NULL DEFAULT 0,
  last_question_id INTEGER NOT NULL DEFAULT 0,
  completed_cycles INTEGER NOT NULL DEFAULT 0,

  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (
    gyan_account_id,
    scope_key
  )
);
ANALYZE sqlite_schema;
CREATE TABLE education_gre_question_details (
  question_id INTEGER PRIMARY KEY,

  
  response_type TEXT NOT NULL DEFAULT 'SINGLE_CHOICE'
    CHECK (response_type IN (
      'SINGLE_CHOICE',
      'MULTI_SELECT',
      'NUMERIC_ENTRY',
      'QUANT_COMPARISON',
      'READING_COMPREHENSION',
      'TEXT_COMPLETION',
      'SENTENCE_EQUIVALENCE'
    )),

  
  section_kind TEXT NOT NULL
    CHECK (section_kind IN ('VERBAL','QUANT')),

  
  stimulus_type TEXT NOT NULL DEFAULT 'NONE'
    CHECK (stimulus_type IN (
      'NONE',
      'TEXT',
      'PASSAGE',
      'TABLE',
      'BAR_GRAPH',
      'LINE_GRAPH',
      'SCATTERPLOT',
      'OTHER_GRAPHIC'
    )),

  stimulus_text TEXT,
  directions_text TEXT,

  
  
  
  
  
  
  
  
  
  
  
  choices_json TEXT,

  
  
  
  
  
  correct_answers_json TEXT,

  
  blank_count INTEGER NOT NULL DEFAULT 0
    CHECK (blank_count BETWEEN 0 AND 3),

  
  numeric_tolerance REAL,

  
  calculator_allowed INTEGER NOT NULL DEFAULT 0
    CHECK (calculator_allowed IN (0,1)),

  
  
  section_number INTEGER
    CHECK (section_number IS NULL OR section_number IN (1,2)),

  section_path TEXT
    CHECK (
      section_path IS NULL OR
      section_path IN ('BASE','EASIER','HARDER')
    ),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
);
CREATE TABLE education_question_response_details (
  question_id INTEGER PRIMARY KEY,

  response_type TEXT NOT NULL DEFAULT 'SINGLE_CHOICE'
    CHECK (response_type IN (
      'SINGLE_CHOICE',
      'MULTI_SELECT',
      'NUMERIC_ENTRY',
      'INTEGER',
      'QUANT_COMPARISON',
      'READING_COMPREHENSION',
      'TEXT_COMPLETION',
      'SENTENCE_EQUIVALENCE',
      'MATCHING',
      'COMPREHENSION'
    )),

  stimulus_type TEXT NOT NULL DEFAULT 'NONE'
    CHECK (stimulus_type IN (
      'NONE',
      'TEXT',
      'PASSAGE',
      'TABLE',
      'BAR_GRAPH',
      'LINE_GRAPH',
      'SCATTERPLOT',
      'OTHER_GRAPHIC'
    )),

  stimulus_text TEXT,
  directions_text TEXT,

  
  
  
  
  
  
  
  
  choices_json TEXT,

  
  
  
  
  correct_answers_json TEXT,

  blank_count INTEGER NOT NULL DEFAULT 0
    CHECK (blank_count BETWEEN 0 AND 10),

  numeric_tolerance REAL,

  calculator_allowed INTEGER NOT NULL DEFAULT 0
    CHECK (calculator_allowed IN (0,1)),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
);
CREATE TABLE education_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  student_id INTEGER NOT NULL,
  grade_code TEXT NOT NULL,
  subject_code TEXT NOT NULL,
  topic_code TEXT NOT NULL,

  question_count INTEGER NOT NULL,
  correct_count INTEGER NOT NULL,
  score_percent INTEGER NOT NULL,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE
);
CREATE TABLE education_attempt_answers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  attempt_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,

  selected_choice TEXT NOT NULL
    CHECK (
      selected_choice IN (
        'A','B','C','D'
      )
    ),

  correct INTEGER NOT NULL
    CHECK (
      correct IN (
        0,1
      )
    ),

  FOREIGN KEY(attempt_id)
    REFERENCES education_attempts(id)
    ON DELETE CASCADE,

  FOREIGN KEY(question_id)
    REFERENCES education_questions(id)
    ON DELETE RESTRICT,

  UNIQUE(
    attempt_id,
    question_id
  )
);
CREATE TABLE education_topic_mastery (
  student_id INTEGER NOT NULL,
  grade_code TEXT NOT NULL,
  subject_code TEXT NOT NULL,
  topic_code TEXT NOT NULL,

  attempts INTEGER NOT NULL DEFAULT 0,
  questions_answered INTEGER NOT NULL DEFAULT 0,
  correct_answers INTEGER NOT NULL DEFAULT 0,
  unique_questions_attempted INTEGER NOT NULL DEFAULT 0,
  score_percent INTEGER NOT NULL DEFAULT 0,

  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY(
    student_id,
    grade_code,
    subject_code,
    topic_code
  ),

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE
);
CREATE TABLE education_subtopic_mastery (
  student_id INTEGER NOT NULL,
  grade_code TEXT NOT NULL,
  subject_code TEXT NOT NULL,
  topic_code TEXT NOT NULL,
  subtopic_code TEXT NOT NULL,

  attempts INTEGER NOT NULL DEFAULT 0,
  questions_answered INTEGER NOT NULL DEFAULT 0,
  correct_answers INTEGER NOT NULL DEFAULT 0,
  unique_questions_attempted INTEGER NOT NULL DEFAULT 0,
  score_percent INTEGER NOT NULL DEFAULT 0,

  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY(
    student_id,
    grade_code,
    subject_code,
    topic_code,
    subtopic_code
  ),

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE
);
CREATE TABLE education_question_metadata (
  question_id INTEGER PRIMARY KEY,

  exam_level TEXT NOT NULL DEFAULT 'BOTH'
    CHECK (
      exam_level IN (
        'MAIN',
        'ADVANCED',
        'BOTH',
        'NEET'
      )
    ),

  question_format TEXT NOT NULL DEFAULT 'SINGLE_CHOICE'
    CHECK (
      question_format IN (
        'SINGLE_CHOICE',
        'NUMERICAL',
        'MULTI_SELECT',
        'INTEGER',
        'MATCHING',
        'COMPREHENSION'
      )
    ),

  syllabus_version TEXT NOT NULL DEFAULT 'JEE_2026',

  quality_status TEXT NOT NULL DEFAULT 'DRAFT'
    CHECK (
      quality_status IN (
        'DRAFT',
        'REVIEWED',
        'PUBLISHED',
        'RETIRED'
      )
    ),

  archetype_code TEXT,
  source_note TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_friends (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  owner_account_id INTEGER NOT NULL,
  friend_account_id INTEGER NOT NULL,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (owner_account_id)
    REFERENCES gyan_accounts(id)
    ON DELETE CASCADE,

  FOREIGN KEY (friend_account_id)
    REFERENCES gyan_accounts(id)
    ON DELETE CASCADE,

  CHECK (
    owner_account_id <> friend_account_id
  ),

  UNIQUE (
    owner_account_id,
    friend_account_id
  )
);
CREATE TABLE nearby_search_cache (
  search_key TEXT PRIMARY KEY,

  service_code TEXT NOT NULL,

  location_mode TEXT NOT NULL
    CHECK (
      location_mode IN (
        'gps',
        'city'
      )
    ),

  city TEXT,
  state TEXT,

  latitude_bucket REAL,
  longitude_bucket REAL,

  search_count INTEGER NOT NULL
    DEFAULT 1,

  registered_result_count INTEGER NOT NULL
    DEFAULT 0,

  external_result_count INTEGER NOT NULL
    DEFAULT 0,

  response_json TEXT NOT NULL,

  first_searched_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  last_searched_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  expires_at TEXT NOT NULL
);
CREATE TABLE nearby_discovered_places (
  provider TEXT NOT NULL,

  provider_place_id TEXT NOT NULL,

  name TEXT NOT NULL,

  address TEXT NOT NULL
    DEFAULT '',

  latitude REAL,
  longitude REAL,

  phone_number TEXT,
  website TEXT,

  categories_json TEXT NOT NULL
    DEFAULT '[]',

  first_seen_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  last_seen_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  seen_count INTEGER NOT NULL
    DEFAULT 1,

  PRIMARY KEY (
    provider,
    provider_place_id
  )
);
CREATE TABLE nearby_discovered_place_services (
  provider TEXT NOT NULL,

  provider_place_id TEXT NOT NULL,

  service_code TEXT NOT NULL,

  seen_count INTEGER NOT NULL
    DEFAULT 1,

  first_seen_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  last_seen_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (
    provider,
    provider_place_id,
    service_code
  )
);
CREATE TABLE education_synthetic_participants (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  synthetic_code TEXT NOT NULL UNIQUE,
  ability_band INTEGER NOT NULL CHECK (ability_band IN (4,5,6,7)),
  program_pool TEXT NOT NULL CHECK (program_pool IN ('JEE','NEET','GRE','RESERVE')),
  initial_timezone TEXT NOT NULL,
  starting_gems INTEGER NOT NULL CHECK (starting_gems >= 0),
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE education_live_test_policy (
  program_code TEXT PRIMARY KEY,
  series_suffix TEXT NOT NULL,
  schedule_timezone TEXT NOT NULL,
  test_start_local TEXT NOT NULL,
  duration_minutes INTEGER NOT NULL,
  question_count INTEGER NOT NULL,
  entry_gem_cost INTEGER NOT NULL DEFAULT 5,
  report_gem_cost INTEGER NOT NULL DEFAULT 15,
  test_fraction_percent INTEGER NOT NULL DEFAULT 10,
  series_epoch_date TEXT NOT NULL,
  series_epoch_number INTEGER NOT NULL,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, country_code TEXT NOT NULL DEFAULT 'IN'
CHECK (country_code IN ('IN','US')));
CREATE TABLE education_live_test_policy_subjects (
  program_code TEXT NOT NULL,
  subject_code TEXT NOT NULL,
  question_count INTEGER NOT NULL CHECK (question_count > 0),
  sort_order INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (program_code, subject_code),
  FOREIGN KEY (program_code)
    REFERENCES education_live_test_policy(program_code)
    ON DELETE CASCADE
);
CREATE TABLE education_live_generation_runs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  schedule_date TEXT NOT NULL,
  program_code TEXT NOT NULL,
  public_code TEXT,
  status TEXT NOT NULL
    CHECK (status IN ('READY','INCOMPLETE','ERROR','SKIPPED')),
  frozen_question_count INTEGER NOT NULL DEFAULT 0,
  message TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE education_live_entry_answers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  live_entry_id INTEGER NOT NULL,

  question_id INTEGER NOT NULL,

  selected_choice TEXT NOT NULL
    CHECK (
      selected_choice IN (
        'A',
        'B',
        'C',
        'D'
      )
    ),

  saved_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    live_entry_id,
    question_id
  )
);
CREATE TABLE platform_settings (
  setting_key TEXT PRIMARY KEY,
  setting_value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "education_live_class_schedule" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  schedule_date TEXT NOT NULL,
  program_code TEXT NOT NULL CHECK (program_code IN ('JEE','NEET','GRE','IELTS','SAT')),
  subject_code TEXT NOT NULL,
  topic_code TEXT,
  topic_name TEXT NOT NULL,
  class_start_local TEXT NOT NULL,
  class_end_local TEXT NOT NULL,
  schedule_timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata',
  sequence_number INTEGER NOT NULL DEFAULT 1,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (schedule_date, program_code, subject_code, sequence_number)
);
CREATE TABLE IF NOT EXISTS "education_live_tests" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  series_number INTEGER NOT NULL,
  series_suffix TEXT NOT NULL
    CHECK (series_suffix IN ('N','J','G','S')),
  public_code TEXT NOT NULL UNIQUE,
  program_code TEXT NOT NULL
    CHECK (program_code IN ('NEET','JEE','GRE','SAT')),
  mock_test_id INTEGER NOT NULL,
  starts_at_utc TEXT NOT NULL,
  schedule_timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata',
  duration_minutes INTEGER NOT NULL DEFAULT 20
    CHECK (duration_minutes > 0),
  entry_gem_cost INTEGER NOT NULL DEFAULT 5
    CHECK (entry_gem_cost >= 0),
  report_gem_cost INTEGER NOT NULL DEFAULT 15
    CHECK (report_gem_cost >= 0),
  status TEXT NOT NULL DEFAULT 'SCHEDULED'
    CHECK (status IN ('SCHEDULED','CANCELLED')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  test_fraction_percent INTEGER NOT NULL DEFAULT 10,
  event_kind TEXT NOT NULL DEFAULT 'WEEKDAY',
  source_schedule_date TEXT,
  visible INTEGER NOT NULL DEFAULT 1
    CHECK (visible IN (0,1)),
  visibility_mode TEXT NOT NULL DEFAULT 'AUTO'
    CHECK (
      visibility_mode IN (
        'AUTO',
        'SHOW',
        'HIDE'
      )
    ), batch_code TEXT, question_paper_gem_cost INTEGER NOT NULL DEFAULT 3
CHECK (question_paper_gem_cost >= 0),
  UNIQUE (series_number, series_suffix)
);
CREATE TABLE education_live_entries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  live_test_id INTEGER NOT NULL,
  participant_type TEXT NOT NULL
    CHECK (participant_type IN ('GYAN','SYNTHETIC')),
  participant_key TEXT NOT NULL,
  entered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  submitted_at TEXT,
  attempt_id INTEGER,
  entry_gem_transaction_key TEXT,
  report_unlocked_at TEXT,
  report_gem_transaction_key TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (live_test_id)
    REFERENCES education_live_tests(id)
    ON DELETE CASCADE,
  UNIQUE (live_test_id, participant_type, participant_key),
  UNIQUE (entry_gem_transaction_key),
  UNIQUE (report_gem_transaction_key)
);
CREATE TABLE education_live_test_questions (
  live_test_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  question_order INTEGER NOT NULL,
  section_code TEXT,
  source_subject_code TEXT,
  source_topic_code TEXT,
  selection_reason TEXT NOT NULL DEFAULT 'TOPIC'
    CHECK (
      selection_reason IN (
        'TOPIC',
        'WEEKLY',
        'REVISION',
        'MANUAL'
      )
    ),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (live_test_id)
    REFERENCES education_live_tests(id)
    ON DELETE CASCADE,
  PRIMARY KEY (live_test_id, question_order),
  UNIQUE (live_test_id, question_id)
);
CREATE TABLE education_live_synthetic_runs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  live_test_id INTEGER NOT NULL,
  synthetic_participant_id INTEGER NOT NULL,
  scheduled_join_offset_seconds INTEGER NOT NULL DEFAULT 0,
  behavior_seed INTEGER NOT NULL,
  completion_profile TEXT NOT NULL
    CHECK (
      completion_profile IN (
        'EARLY',
        'NORMAL',
        'LATE',
        'ABANDON'
      )
    ),
  run_status TEXT NOT NULL DEFAULT 'PLANNED'
    CHECK (
      run_status IN (
        'PLANNED',
        'ENTERED',
        'SUBMITTED',
        'ABANDONED',
        'FAILED',
        'SKIPPED'
      )
    ),
  entered_at TEXT,
  submitted_at TEXT,
  error_message TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (live_test_id)
    REFERENCES education_live_tests(id)
    ON DELETE CASCADE,
  FOREIGN KEY (synthetic_participant_id)
    REFERENCES education_synthetic_participants(id)
    ON DELETE CASCADE,
  UNIQUE (live_test_id, synthetic_participant_id)
);
CREATE TABLE education_live_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  live_test_id INTEGER NOT NULL,
  live_entry_id INTEGER NOT NULL UNIQUE,
  participant_type TEXT NOT NULL
    CHECK (participant_type IN ('GYAN','SYNTHETIC')),
  participant_key TEXT NOT NULL,
  question_count INTEGER NOT NULL DEFAULT 0,
  answered_count INTEGER NOT NULL DEFAULT 0,
  correct_count INTEGER NOT NULL DEFAULT 0,
  incorrect_count INTEGER NOT NULL DEFAULT 0,
  unanswered_count INTEGER NOT NULL DEFAULT 0,
  raw_score REAL NOT NULL DEFAULT 0,
  started_at TEXT,
  submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (live_test_id)
    REFERENCES education_live_tests(id)
    ON DELETE CASCADE,
  FOREIGN KEY (live_entry_id)
    REFERENCES education_live_entries(id)
    ON DELETE CASCADE,
  UNIQUE (live_test_id, participant_type, participant_key)
);
CREATE TABLE education_live_attempt_answers (
  attempt_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  question_order INTEGER NOT NULL,
  selected_choice TEXT
    CHECK (
      selected_choice IS NULL
      OR selected_choice IN ('A','B','C','D')
    ),
  correct_choice TEXT NOT NULL
    CHECK (correct_choice IN ('A','B','C','D')),
  is_correct INTEGER NOT NULL
    CHECK (is_correct IN (0,1)),
  section_code TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (attempt_id)
    REFERENCES education_live_attempts(id)
    ON DELETE CASCADE,
  PRIMARY KEY (attempt_id, question_id)
);
CREATE TABLE education_live_test_batches (
  batch_code TEXT PRIMARY KEY,
  label TEXT NOT NULL,
  start_date TEXT NOT NULL,
  end_date TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (start_date <= end_date)
);
CREATE TABLE education_class_interests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL,
  program_code TEXT NOT NULL
    CHECK (program_code IN ('JEE','NEET','SAT')),
  schedule_date TEXT NOT NULL,
  subject_code TEXT NOT NULL,
  topic_code TEXT,
  topic_name TEXT NOT NULL,
  class_start_local TEXT NOT NULL,
  class_end_local TEXT NOT NULL,
  schedule_timezone TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'NEW'
    CHECK (status IN ('NEW','CONTACTED','REGISTERED','CLOSED')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (email, program_code, schedule_date, subject_code)
);
